package dev.ghostty.android.sample;

import java.util.*;

/** Shortcut groups and the runtime panel use exactly the same persisted order. */
public final class ShortcutsSettingsActivity extends InputSettingsActivity {
    private String previewGroup="Upload";
    private android.widget.LinearLayout previewArea;
    private void shortcutPreview(){
        android.widget.LinearLayout canvas=column();canvas.setPadding(dp(12),dp(12),dp(12),dp(12));android.graphics.drawable.GradientDrawable gradient=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{UiTheme.background(this,0xff063a18),UiTheme.background(this,0xff164d48)});gradient.setCornerRadius(dp(12));canvas.setBackground(gradient);
        boolean compact=getResources().getConfiguration().screenHeightDp<480;android.widget.TextView caption=label(AppLanguage.tr(R.string.input_live_preview),14,SampleUi.TEXT);if(compact)caption.setVisibility(android.view.View.GONE);caption.setGravity(android.view.Gravity.CENTER);canvas.addView(caption,new android.widget.LinearLayout.LayoutParams(-1,0,1));previewArea=column();previewArea.setBackground(SampleUi.surface(this,CARD,16));canvas.addView(previewArea);renderPreviewPanel();android.widget.LinearLayout.LayoutParams toolbarParams=new android.widget.LinearLayout.LayoutParams(-1,dp(InputToolbar.HEIGHT_DP));toolbarParams.topMargin=dp(8);canvas.addView(layoutPreview("layout_toolbar"),toolbarParams);body.addView(canvas,new android.widget.LinearLayout.LayoutParams(-1,dp(compact?248:304)));
    }
    private void renderPreviewPanel(){
        previewArea.removeAllViews();InputPreferences config=controls();java.util.List<String> names=new java.util.ArrayList<>();if(config.flag("shortcut_upload",true))names.add("Upload");names.addAll(config.list("groups"));if(!names.contains(previewGroup))previewGroup=names.isEmpty()?"":names.get(0);
        android.widget.HorizontalScrollView tabs=new android.widget.HorizontalScrollView(this);tabs.setHorizontalScrollBarEnabled(false);android.widget.LinearLayout buttons=row();
        for(String group:names){android.view.View tab;if(config.flag("shortcut_icons_only",true)&&(group.equals("Claude")||group.equals("Codex"))){android.widget.ImageView logo=new android.widget.ImageView(this);logo.setImageResource(group.equals("Codex")?R.drawable.agent_openai:R.drawable.agent_claude);logo.setImageTintList(android.content.res.ColorStateList.valueOf(UiTheme.foreground(this,group.equals(previewGroup)?SampleUi.GREEN:SampleUi.MUTED)));logo.setPadding(dp(12),dp(8),dp(12),dp(8));tab=logo;}else{android.widget.TextView word=label(config.flag("shortcut_icons_only",true)?InputActions.groupSymbol(group):InputText.localize(group),14,group.equals(previewGroup)?SampleUi.GREEN:SampleUi.MUTED);word.setGravity(android.view.Gravity.CENTER);tab=word;}tab.setContentDescription(group+AppLanguage.tr(R.string.input_preview));tab.setOnClickListener(v->{previewGroup=group;renderPreviewPanel();});buttons.addView(tab,new android.widget.LinearLayout.LayoutParams(dp(config.flag("shortcut_icons_only",true)?48:84),dp(48)));}tabs.addView(buttons);previewArea.addView(tabs);
        android.widget.HorizontalScrollView keys=new android.widget.HorizontalScrollView(this);keys.setHorizontalScrollBarEnabled(false);android.widget.LinearLayout columns=row();
        if(previewGroup.equals("Upload")){for(String source:new String[]{"camera","image","file"}){android.widget.ImageView icon=SampleUi.icon(this,source,SampleUi.TEXT);icon.setPadding(dp(24),dp(24),dp(24),dp(24));columns.addView(icon,new android.widget.LinearLayout.LayoutParams(dp(80),dp(84)));}}
        else{java.util.List<String> ids=config.list("group_"+previewGroup);for(int i=0;i<ids.size();i+=2){android.widget.LinearLayout column=column();for(int j=i;j<Math.min(i+2,ids.size());j++){InputButton key=new InputButton(this,config.action(ids.get(j)),config.flag("modifier_icons",false));key.setEnabled(false);android.widget.LinearLayout.LayoutParams kp=new android.widget.LinearLayout.LayoutParams(key.preferredWidth(104,160),dp(48));kp.setMargins(dp(2),dp(2),dp(2),dp(2));column.addView(key,kp);}columns.addView(column);}}keys.addView(columns);previewArea.addView(keys,new android.widget.LinearLayout.LayoutParams(-1,dp(104)));
    }
    @Override protected void renderSettings(){
        heading.setText(AppLanguage.tr(R.string.input_shortcuts_3));section(AppLanguage.tr(R.string.input_preview));shortcutPreview();section(AppLanguage.tr(R.string.input_enabled_groups_drag_to_reorder));List<String> groups=controls().list("groups");ordered("groups",groups,true);
        section(AppLanguage.tr(R.string.input_available_groups));for(String name:InputActions.GROUPS.keySet())if(!groups.contains(name))item("＋ "+name,null,"plus",()->{List<String> next=controls().list("groups");next.add(name);controls().save("groups",next);refreshSettings();});
        section(AppLanguage.tr(R.string.input_panel));inputToggle(AppLanguage.tr(R.string.input_hide_label_text),AppLanguage.tr(R.string.input_show_group_icons_only),"shortcut_icons_only",true);inputToggle(AppLanguage.tr(R.string.input_show_upload_panel),AppLanguage.tr(R.string.input_camera_photos_and_files),"shortcut_upload",true);
        item(AppLanguage.tr(R.string.input_new_shortcut),AppLanguage.tr(R.string.input_add_to_favorites_2),"plus",()->editShortcut(null,"group_Favorites"));
        item(AppLanguage.tr(R.string.input_restore_default_groups),null,"history",()->{controls().reset("groups");for(String g:InputActions.GROUPS.keySet())controls().reset("group_"+g);refreshSettings();});
    }
}
